describe('verifyWithJwks typ', () => {
  const payload = { message: 'hello world' }
  const kid = 'dummy'

  const setup = async (typ: string) => {
    const keyPair = await crypto.subtle.generateKey(
      {
        name: 'RSASSA-PKCS1-v1_5',
        modulusLength: 2048,
        publicExponent: new Uint8Array([1, 0, 1]),
        hash: 'SHA-256',
      },
      true,
      ['sign', 'verify']
    )

    const encode = (obj: object) => encodeBase64Url(utf8Encoder.encode(JSON.stringify(obj)).buffer)
    const signingInput = `${encode({ alg: 'RS256', typ, kid })}.${encode(payload)}`
    const signature = await signing(
      keyPair.privateKey,
      'RS256',
      utf8Encoder.encode(signingInput)
    )
    const token = `${signingInput}.${encodeBase64Url(signature)}`

    const jwk = await crypto.subtle.exportKey('jwk', keyPair.publicKey)
    return { token, keys: [{ ...jwk, kid, use: 'sig', alg: 'RS256' }] }
  }

  it('Should reject a token whose typ does not match the expected typ', async () => {
    const { token, keys } = await setup('at+jwt')

    await expect(
      verifyWithJwks(token, {
        keys,
        allowedAlgorithms: ['RS256'],
        verification: { typ: 'JWT' },
      })
    ).rejects.toThrow(JwtHeaderInvalid)
  })

  it('Should accept a token whose typ matches case-insensitively without the application/ prefix', async () => {
    const { token, keys } = await setup('application/AT+JWT')

    await expect(
      verifyWithJwks(token, {
        keys,
        allowedAlgorithms: ['RS256'],
        verification: { typ: 'at+jwt' },
      })
    ).resolves.toEqual(payload)
  })

  it('Should reject a non-JWT typ by default', async () => {
    const { token, keys } = await setup('at+jwt')

    await expect(verifyWithJwks(token, { keys, allowedAlgorithms: ['RS256'] })).rejects.toThrow(
      JwtHeaderInvalid
    )
  })
})

